def test_option_with_optional_value_and_default(runner):
    @click.command()
    @click.option("--name", is_flag=False, flag_value="Flag", default="Default")
    def cli(name):
        return name

    cases = ([], ["--name"], ["--name=Alice"], ["--name", "Alice"])
    expected = ("Default", "Flag", "Alice", "Alice")

    for args, want in zip(cases, expected):
        result = runner.invoke(cli, args)
        assert result.exception is None
        assert result.return_value == want


def test_option_with_optional_value_and_invalid_explicit_value(runner):
    @click.command()
    @click.option("--count", is_flag=False, flag_value=0, default=1, type=int)
    def cli(count):
        return count

    result = runner.invoke(cli, ["--count"])
    assert result.exception is None
    assert result.return_value == 0

    result = runner.invoke(cli, ["--count", "2"])
    assert result.exception is None
    assert result.return_value == 2

    result = runner.invoke(cli, ["--count", "nope"])
    assert isinstance(result.exception, click.exceptions.BadParameter)
    assert "Invalid value for '--count': 'nope' is not a valid integer." in result.output
